680→    #[test]
681→    fn cleanup_removes_orphaned_steps() {
682→        let temp = TempDir::new().unwrap();
683→        let project = super::super::ProjectId::from_path(temp.path()).unwrap();
684→        let mut state = StateStore::new(&project);
685→
686→        // Add orphan step state (not in any run)
687→        state.record_step_result(
688→            "orphan",
689→            StepStatus::Success,
690→            std::time::Duration::ZERO,
691→            None,
692→        );
693→
694→        // Add a run with a different step
695→        let record = super::super::RunRecord {
696→            timestamp: Utc::now(),
697→            workflow: "default".to_string(),
698→            duration_ms: 1000,
699→            status: super::super::RunStatus::Success,
700→            steps_run: vec!["kept".to_string()],
701→            steps_skipped: vec![],
702→            error: None,
703→        };
704→        state.record_run(record);
705→
706→        // Add the kept step state
707→        state.record_step_result("kept", StepStatus::Success, std::time::Duration::ZERO, None);
708→
709→        state.cleanup(50);
710→
711→        assert!(state.get_step("orphan").is_none());
712→        assert!(state.get_step("kept").is_some());
713→    }
