        let project = super::super::ProjectId::from_path(temp.path()).unwrap();
        let mut state = StateStore::new(&project);

        let record = super::super::RunRecord {
            timestamp: Utc::now(),
            workflow: "default".to_string(),
            duration_ms: 1000,
            status: super::super::RunStatus::Success,
