        state.record_run(record);

        let history = state.step_history("test");
        assert_eq!(history.len(), 1);
        assert_eq!(history[0].status, StepStatus::Skipped);
    }

    #[test]
    fn step_history_empty_for_unknown_step() {
        let temp = TempDir::new().unwrap();
