//! Centralized path resolution using platform-standard directories.

use std::path::PathBuf;

/// Returns the platform-standard configuration directory for Bivvy.
///
/// Uses `dirs::config_dir()` to respect XDG conventions:
/// - Linux: `$XDG_CONFIG_HOME/bivvy` or `~/.config/bivvy`
/// - macOS: `~/Library/Application Support/bivvy`
/// - Windows: `{FOLDERID_RoamingAppData}\bivvy`
pub fn config_dir() -> PathBuf {
    dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("bivvy")
}

/// Returns the platform-standard data directory for Bivvy.
///
/// Uses `dirs::data_local_dir()` to respect XDG conventions:
/// - Linux: `$XDG_DATA_HOME/bivvy` or `~/.local/share/bivvy`
/// - macOS: `~/Library/Application Support/bivvy`
/// - Windows: `{FOLDERID_LocalAppData}\bivvy`
pub fn data_dir() -> PathBuf {
    dirs::data_local_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("bivvy")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn config_dir_does_not_use_dot_bivvy() {
        let path = config_dir();
        assert!(
            !path.to_string_lossy().contains(".bivvy"),
            "config_dir should not use .bivvy: {:?}",
            path
        );
    }

    #[test]
    fn data_dir_does_not_use_dot_bivvy() {
        let path = data_dir();
        assert!(
            !path.to_string_lossy().contains(".bivvy"),
            "data_dir should not use .bivvy: {:?}",
            path
        );
    }

    #[test]
    fn config_dir_ends_with_bivvy() {
        let path = config_dir();
        assert!(
            path.ends_with("bivvy"),
            "config_dir should end with 'bivvy': {:?}",
            path
        );
    }

    #[test]
    fn data_dir_ends_with_bivvy() {
        let path = data_dir();
        assert!(
            path.ends_with("bivvy"),
            "data_dir should end with 'bivvy': {:?}",
            path
        );
    }

    #[test]
    fn config_dir_uses_platform_config_location() {
        let path = config_dir();
        if let Some(expected_base) = dirs::config_dir() {
            assert_eq!(path, expected_base.join("bivvy"));
        }
    }

    #[test]
    fn data_dir_uses_platform_data_location() {
        let path = data_dir();
        if let Some(expected_base) = dirs::data_local_dir() {
            assert_eq!(path, expected_base.join("bivvy"));
        }
    }
}

